-- migrate:up
-- LAYOUT-SWEEP (owner, 11 Oct 2026): an organisation's own logo, as an organisation setting, so every company shows
-- its own. Pulse puts it in the shell, on the sign-in page, in e-mails and on printed copies (payslips, policies).
-- Admins change it in Settings → Organisation through pulse.org_brand_save(); anyone may read it (the sign-in page
-- shows it before anyone signs in). The EA organisation starts with the official logo from its branding brief.

create table pulse.org_brand (
 org_id uuid primary key references pulse.org(id) on delete cascade,
 mark bytea, mark_mime text,                -- the square tile (Pulse's rail, small places)
 logo bytea, logo_mime text,                -- the horizontal lock-up on light backgrounds
 logo_dark bytea, logo_dark_mime text,      -- the same on dark backgrounds
 logo_png bytea,                            -- a raster of the lock-up for e-mail (mail clients do not show SVG)
 version int not null default 1,
 updated_by uuid,                           -- no foreign key to pulse.person (release smoke cleanup deletes people)
 updated_at timestamptz not null default now(),
 check (coalesce(mark_mime,'image/png') in ('image/svg+xml','image/png','image/webp','image/jpeg')
   and coalesce(logo_mime,'image/png') in ('image/svg+xml','image/png','image/webp','image/jpeg')
   and coalesce(logo_dark_mime,'image/png') in ('image/svg+xml','image/png','image/webp','image/jpeg')),
 check (coalesce(octet_length(mark),0) <= 524288 and coalesce(octet_length(logo),0) <= 524288
   and coalesce(octet_length(logo_dark),0) <= 524288 and coalesce(octet_length(logo_png),0) <= 524288)
);
alter table pulse.org_brand enable row level security;
alter table pulse.org_brand force row level security;
create policy tenant on pulse.org_brand using (org_id=pulse.current_org()) with check (org_id=pulse.current_org());
grant select on pulse.org_brand to pulse_api, pulse_worker;
create trigger audit_mutation after insert or update or delete on pulse.org_brand for each row execute function pulse.audit_mutation();

-- Set or clear one picture (kind: mark, logo, logo_dark, logo_png). An individual organisation admin only.
create function pulse.org_brand_save(p_kind text, p_bytes bytea, p_mime text) returns int
 language plpgsql security definer set search_path=pulse,pg_temp as $$
declare v_version int;
begin
 if not pulse.viewer_is('admin') or pulse.current_viewer() is null then raise exception 'An individual organisation admin changes the logo' using errcode='42501'; end if;
 if p_kind not in ('mark','logo','logo_dark','logo_png') then raise exception 'Unknown picture' using errcode='22023'; end if;
 if p_bytes is not null and (p_mime is null or p_mime not in ('image/svg+xml','image/png','image/webp','image/jpeg')) then raise exception 'Choose an SVG, PNG, WebP or JPEG' using errcode='22023'; end if;
 if p_kind='logo_png' and p_bytes is not null and p_mime<>'image/png' then raise exception 'The e-mail logo is a PNG' using errcode='22023'; end if;
 insert into pulse.org_brand(org_id) values (pulse.current_org()) on conflict (org_id) do nothing;
 execute format('update pulse.org_brand set %I=$1%s, version=version+1, updated_by=pulse.current_viewer(), updated_at=now() where org_id=pulse.current_org() returning version',
   p_kind, case when p_kind='logo_png' then '' else format(', %I=$2', p_kind||'_mime') end)
   using p_bytes, case when p_bytes is null then null else p_mime end into v_version;
 insert into pulse.record_change(org_id,entity_type,entity_id,field,old_value,new_value,changed_by)
  values (pulse.current_org(),'org',pulse.current_org(),'brand.'||p_kind,null,case when p_bytes is null then 'removed' else p_mime||' · '||octet_length(p_bytes)||' bytes' end,pulse.current_viewer());
 return v_version;
end $$;
revoke all on function pulse.org_brand_save(text,bytea,text) from public;
grant execute on function pulse.org_brand_save(text,bytea,text) to pulse_api;

-- Estate Autopilots: the official logo (EA BRANDING BRIEF, April 2026; packages/design-system/brand/org/estate-autopilots).
do $seed$
declare v_org uuid;
begin
 select id into v_org from pulse.org where code='EA' and status='active';
 if v_org is null then raise notice 'No active EA organisation: no logo seeded'; return; end if;
 perform set_config('pulse.org_id',v_org::text,true);
